refentry.refsect1:
&reftitle.description;
publicYaf_Route_Map::__construct boolcontroller_preferfalse stringdelimiter''
Construit une route de type carte. Une route de type carte associe l'URI entière à un nom de contrôleur ou à un nom d'action.

  &reftitle.examples;

   Exemple avec Yaf_Route_Map


<?php
/**
 * Ajoute une route de type carte à la pile de routes de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
    new Yaf_Route_Map());
?>


   &example.outputs.similar;


/* pour http://yourdomain.com/product/foo/bar
 * la requête portera les valeurs suivantes :
 */
array(
  "action" => "product_foo_bar",
)




   Exemple avec Yaf_Route_Map


<?php
/**
 * Ajoute une route de type carte avec un délimiteur à la pile de routes de Yaf_Router
 */
Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
    new Yaf_Route_Map(true, "_"));
?>


   &example.outputs.similar;


/* pour http://yourdomain.com/user/list/_/foo/22
 * la requête portera les valeurs suivantes :
 */
array(
    "controller" => "User_List",
)

/**
 * et les paramètres de requête :
 */
array(
  "foo" => "22",
)




   Exemple avec Yaf_Route_Map


<?php
/**
 * Ajoute une route de type carte à la pile de routes en appelant addConfig
 */
$config = array(
    "name" => array(
       "type"             => "map", // route Yaf_Route_Map
       "controllerPrefer" => FALSE,
       "delimiter"        => "#!",
    ),
);
Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
    new Yaf_Config_Simple($config));
?>
